// Limpia lo que escribió el cliente y genera el número de solicitud.
const j = $json;
let pedido = String(j.pedido || '').trim().toUpperCase().replace(/\s+/g, '');
if (/^\d+$/.test(pedido)) pedido = 'PED-' + pedido;
if (/^PED\d+$/.test(pedido)) pedido = pedido.replace('PED', 'PED-');
const fotos = Object.values($input.item.binary || {});
const letras = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const azar = Array.from({ length: 4 }, () => letras[Math.floor(Math.random() * letras.length)]).join('');
return { json: {
  solicitud: 'DEV-' + $now.toFormat('yyMMdd') + '-' + azar,
  pedido, correo: String(j.correo || '').trim().toLowerCase(),
  producto: String(j.producto || '').trim().slice(0, 200), motivo: String(j.motivo || '').trim().slice(0, 2000),
  fotos: fotos.length, fotos_nombres: fotos.map(f => f.fileName).join(', ').slice(0, 500),
} };

// Comprueba pedido + correo, plazo y que no haya otra solicitud abierta del mismo producto.
const s = $('Normalizar').first().json;
const p = ($('Buscar pedido').first().json.data || [])[0];
const previas = $json.data || [];
const plano = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const palabras = t => plano(t).split(/[^a-z0-9]+/).filter(w => w.length >= 4);
const parecido = (a, b) => palabras(a).some(w => plano(b).includes(w));
let error = '';
// Mismo mensaje si no existe o si el correo no coincide: no se revela qué pedidos existen.
if (!p || plano(p.correo) !== plano(s.correo))
  error = 'No encontramos ningún pedido con ese número y ese correo. Revisa el correo de confirmación de tu compra.';
const abierta = !error && previas.find(r => r.estado !== 'rechazada' && parecido(r.producto, s.producto));
if (abierta) error = `Ya tienes una solicitud abierta para este producto: <b>${abierta.solicitud}</b> (${abierta.estado}). Te escribiremos al correo del pedido.`;
// La fecha del pedido es medianoche (UTC o local según quién la guardó): +12 h y se toma el día.
const compra = p ? DateTime.fromISO(String(p.fecha), { zone: 'utc' }).plus({ hours: 12 }).toISODate() : null;
const dias = compra ? Math.round(DateTime.fromISO($now.toISODate()).diff(DateTime.fromISO(compra), 'days').days) : null;
return [{ json: { ...s, valido: !error, error, cliente: p?.cliente || '', productos: p?.productos || '', importe_pedido: p?.importe ?? null,
  fecha_pedido: compra, dias, en_plazo: dias !== null && dias <= 30, producto_en_pedido: p ? parecido(s.producto, p.productos) : false } }];

