// Junta la IA con las reglas de la tienda. La IA clasifica; las reglas mandan.
const s = $('Validar').item.json;
let ia = null;
try { ia = JSON.parse(String($json.text || '').match(/\{[\s\S]*\}/)[0]); } catch {}
const m = s.motivo.toLowerCase();
const CATS = ['defectuoso', 'talla_medida', 'no_esperado', 'llego_tarde', 'otro'];
const porReglas = /rot[oa]|defect|no funciona|no enciende|no carga|falla|averiad|da[ñn]ad|rajad|descosid|roto/.test(m) ? 'defectuoso'
  : /talla|medida|grande|peque|ajusta|apretad|holgad|me queda/.test(m) ? 'talla_medida'
  : /tarde|retras|demor/.test(m) ? 'llego_tarde'
  : /esperaba|diferente|distint|color|foto|descripci|calidad|no me gust/.test(m) ? 'no_esperado' : 'otro';
const categoria = CATS.includes(ia?.categoria) ? ia.categoria : porReglas;
const pide = ['reembolso', 'cambio'].includes(ia?.pide) ? ia.pide : /cambi|otro igual|otra talla|reemplaz|sustitu/.test(m) ? 'cambio' : 'no_dice';
let resolucion = { defectuoso: pide === 'cambio' ? 'cambio' : 'reembolso', talla_medida: 'cambio', no_esperado: 'reembolso', llego_tarde: 'reembolso' }[categoria]
  || (['reembolso', 'cambio', 'rechazo'].includes(ia?.resolucion) ? ia.resolucion : 'rechazo');
let explicacion = String(ia?.explicacion || '').slice(0, 300) || `Clasificado por reglas como ${categoria}.`;
let estado = 'pendiente', motivo_rechazo = '';
if (!s.en_plazo) {
  estado = 'rechazada'; resolucion = 'rechazo';
  motivo_rechazo = `Fuera del plazo de ${30} días: el pedido es del ${DateTime.fromISO(s.fecha_pedido).toFormat('dd/MM/yyyy')} (${s.dias} días).`;
  explicacion = motivo_rechazo;
} else if (resolucion === 'rechazo') motivo_rechazo = explicacion;
const avisos = [];
if (!s.producto_en_pedido) avisos.push('el producto no aparece tal cual en el pedido');
if (categoria === 'defectuoso' && !s.fotos) avisos.push('defectuoso sin fotos: pedirlas');
const correo_valido = /^[\w.+-]+@[\w-]+(\.[\w-]+)+$/.test(s.correo) && !/@(ejemplo|example)\.(com|org|net)$|\.(test|invalid|local)$/.test(s.correo);
return { json: { ...s, categoria, pide, resolucion, explicacion, estado, motivo_rechazo, nota: avisos.join('; '),
  resumen: String(ia?.resumen || s.motivo.slice(0, 80)), origen: ia ? 'ia' : 'reglas', correo_valido } };

