// Valida la petición: {"solicitud":"DEV-...","estado":"aprobada|rechazada|pendiente","resolucion":"reembolso|cambio","nota":"..."}
const b = $json.body || {};
const solicitud = String(b.solicitud || '').trim().toUpperCase();
const estado = String(b.estado || '').trim().toLowerCase();
const resolucion = String(b.resolucion || '').trim().toLowerCase();
const nota = String(b.nota || '').trim().slice(0, 500);
let error = '';
if (!/^DEV-\d{6}-[A-Z0-9]{4}$/.test(solicitud)) error = 'solicitud no válida (formato DEV-AAMMDD-XXXX)';
else if (!['aprobada', 'rechazada', 'pendiente'].includes(estado)) error = 'estado debe ser aprobada, rechazada o pendiente';
else if (resolucion && !['reembolso', 'cambio'].includes(resolucion)) error = 'resolucion debe ser reembolso o cambio';
return { json: { ok: !error, codigo: error ? 400 : 200, error, solicitud, estado, resolucion, nota } };

// Busca la solicitud y prepara el cambio.
const p = $('Revisar petición').item.json;
const r = ($json.data || [])[0];
if (!r) return { json: { ...p, ok: false, codigo: 404, error: 'no existe la solicitud ' + p.solicitud } };
const resolucion = p.estado === 'aprobada' ? (p.resolucion || (r.resolucion === 'rechazo' ? 'reembolso' : r.resolucion)) : r.resolucion;
const motivo_rechazo = p.estado === 'rechazada' ? (p.nota || r.motivo_rechazo || 'No cumple la política de devoluciones.') : '';
const cambia = r.estado !== p.estado || resolucion !== r.resolucion;
const correo_valido = /^[\w.+-]+@[\w-]+(\.[\w-]+)+$/.test(r.correo || '') && !/@(ejemplo|example)\.(com|org|net)$|\.(test|invalid|local)$/.test(r.correo);
return { json: { ...p, ok: true, codigo: 200, cambia, anterior: r.estado, fila: r, resolucion, motivo_rechazo,
  avisar: cambia && correo_valido && p.estado !== 'pendiente' } };

